package hu.boltseged.account;
import org.junit.jupiter.api.Test; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import java.math.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AccountProfileControllerTest {@Test void customerProfileUpdatePreservesEmailPricingRoleAndActive(){Account account=new Account(null,"customer@example.com","hash","CUSTOMER");account.update(null,null,null,null,"customer@example.com","FIXED",new BigDecimal("1000"));account.setActive(false);AccountRepository repo=mock(AccountRepository.class);when(repo.save(account)).thenReturn(account);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(account,null));new AccountProfileController(repo).update(new AccountProfileController.ProfileRequest("Company","Tax","Address","Contact"));assertEquals("Company",account.getCompanyName());assertEquals("customer@example.com",account.getEmail());assertEquals("FIXED",account.getPricingType());assertEquals(new BigDecimal("1000"),account.getPricingValue());assertEquals("CUSTOMER",account.getRole());assertFalse(account.isActive());}@Test void savesSeparateSenderAndPickupAddresses(){Account account=new Account(null,"customer@example.com","hash","CUSTOMER");AccountRepository repo=mock(AccountRepository.class);when(repo.save(account)).thenReturn(account);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(account,null));AccountProfileController.Profile profile=new AccountProfileController(repo).update(new AccountProfileController.ProfileRequest("Legal Company","Tax","Billing","Legal Contact","hu","1051","Budapest","Legal Street",null,null,"+361","Pickup Company","Pickup Contact","de","10115","Berlin","Pickup Street",null,null,"+4930","pickup@example.com"));assertEquals("HU",account.getSenderCountryCode());assertEquals("Legal Street",account.getSenderAddressLine1());assertEquals("DE",account.getPickupCountryCode());assertEquals("Pickup Street",account.getPickupAddressLine1());assertEquals("pickup@example.com",profile.pickupEmail());}}
